SELECT cp.cp_department, cd.cd_gender, SUM(cr.cr_return_amount) AS total_return_amount, AVG(cr.cr_return_quantity) AS avg_return_quantity FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk WHERE cp.cp_type = 'bi-annual' AND cd.cd_marital_status = 'W' GROUP BY cp.cp_department, cd.cd_gender ORDER BY total_return_amount DESC LIMIT 1000
